\begin{tikzpicture}[
    pantalla/.style={draw=BrandBlue, very thick, rounded corners, fill=white},
    bloque/.style={fill=PracticeBody, draw=PracticeTitle, thick}
]
    \node[font=\bfseries] at (1.8,4.5) {Móvil};
    \draw[pantalla] (0,0) rectangle (3.6,4.1);
    \draw[bloque] (0.35,3.25) rectangle (3.25,3.7);
    \draw[bloque] (0.35,2.15) rectangle (3.25,3.0);
    \draw[bloque] (0.35,1.05) rectangle (3.25,1.9);
    \draw[bloque] (0.35,0.3) rectangle (3.25,0.8);

    \node[font=\bfseries] at (8.1,4.5) {Pantalla amplia};
    \draw[pantalla] (4.5,0) rectangle (11.7,4.1);
    \draw[bloque] (4.85,3.25) rectangle (11.35,3.7);
    \draw[bloque] (4.85,1.15) rectangle (6.8,3.0);
    \draw[bloque] (7.15,1.15) rectangle (9.1,3.0);
    \draw[bloque] (9.45,1.15) rectangle (11.35,3.0);
    \draw[bloque] (4.85,0.3) rectangle (11.35,0.8);
\end{tikzpicture}

\begin{tikzpicture}[
    marco/.style={draw=BrandBlue, very thick, fill=gray!5},
    imagen/.style={draw=PracticeTitle, thick, fill=PracticeBody}
]
    \node[font=\bfseries] at (2.6,3.5) {\texttt{cover}};
    \draw[marco] (0,0.5) rectangle (5.2,3);
    \draw[imagen] (0,0.5) rectangle (5.2,3);
    \draw[dashed, thick] (0.8,0.5) rectangle (4.4,3);
    \node[align=center] at (2.6,1.75) {cubre el marco\\y puede recortar};

    \node[font=\bfseries] at (8.7,3.5) {\texttt{contain}};
    \draw[marco] (6.0,0.5) rectangle (11.2,3);
    \draw[imagen] (6.8,0.5) rectangle (10.4,3);
    \node[align=center] at (8.6,1.75) {muestra todo\\y puede dejar espacio};
\end{tikzpicture}

\begin{tikzpicture}[
    etapa/.style={draw=BrandBlue, thick, rounded corners, minimum width=3cm,
        minimum height=1.1cm, align=center},
    flecha/.style={->, >=Latex, very thick}
]
    \node[etapa, fill=IdeaBody] (m) at (1.8,2) {Reglas base\\una columna};
    \node[etapa, fill=PracticeBody] (t) at (6.2,2)
        {\texttt{min-width: 700px}\\dos columnas};
    \node[etapa, fill=ResultBody] (d) at (10.6,2)
        {\texttt{min-width: 1000px}\\composición amplia};
    \draw[flecha] (m.east) -- (t.west);
    \draw[flecha] (t.east) -- (d.west);
\end{tikzpicture}

\begin{tikzpicture}[
    node distance=1.3cm,
    estado/.style={draw=BrandBlue, thick, rounded corners, minimum width=3cm,
        minimum height=0.8cm, fill=IdeaBody, align=center},
    flecha/.style={-{Latex[length=3mm]}, thick}
]
    \node[estado] (normal) {estado normal};
    \node[estado, right=of normal] (hover) {\texttt{:hover}};
    \node[estado, right=of hover] (focus) {\texttt{:focus}};
    \draw[flecha] (normal) -- node[above]{puntero} (hover);
    \draw[flecha] (normal) to[bend right=22] node[below]{teclado} (focus);
\end{tikzpicture}

\begin{tikzpicture}[
    estado/.style={draw=BrandBlue, thick, rounded corners, minimum width=3.4cm,
        minimum height=1.2cm, align=center},
    flecha/.style={<->, >=Latex, very thick}
]
    \node[estado, fill=IdeaBody] (a) at (0,0) {estado inicial\\\texttt{translateY(0)}};
    \node[estado, fill=ResultBody] (b) at (6,0) {estado final\\\texttt{translateY(-6px)}};
    \draw[flecha] (a) -- node[above]{220 ms · \texttt{ease}} (b);
\end{tikzpicture}

\begin{tikzpicture}[
    estado/.style={draw=BrandBlue, thick, rounded corners, minimum width=2.5cm,
        minimum height=1cm, align=center},
    flecha/.style={->, >=Latex, thick}
]
    \node[estado, fill=WarnBody] (a) at (0,0) {0\%\\oculto y abajo};
    \node[estado, fill=IdeaBody] (b) at (4.3,0) {50\%\\en movimiento};
    \node[estado, fill=ResultBody] (c) at (8.6,0) {100\%\\visible y ubicado};
    \draw[flecha] (a.east) -- (b.west);
    \draw[flecha] (b.east) -- (c.west);
\end{tikzpicture}
